insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 35, 'E dizes: Sou inocente, pois certamente sua ira já se afastou de mim. Eis que eu disputarei em juízo contigo, porque disseste: Não tenho pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 36, 'Por que tu te desvias tanto, mudando teus caminhos? Também serás envergonhada pelo Egito, tal como foste envergonhada pela Assíria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 2, 37, 'Também sairás daqui com as mãos sobre tua cabeça; porque o SENHOR rejeitou tuas confianças, e nelas não terás sucesso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 3, 1, 'Dizem: Se um homem deixar sua mulher, e ela for embora dele, e se juntar a outro homem, por acaso ele voltará a ela? Não será tal terra contaminada por completo? Tu porém tem te prostituído com muitos amantes; mas volta-te a mim, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 3, 2, 'Levanta teus olhos aos lugares altos, e vê onde não tenhas te prostituído; tu te sentavas para eles nos caminhos, como árabe no deserto; e assim contaminaste a terra com tuas prostituições e com tua malícia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 3, 3, 'Por isso as águas foram retidas, e não houve a chuva tardia; porém tu tens a testa de uma prostituta, [e] não aceitas ter vergonha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 3, 4, 'Não foi agora que clamaste a mim: Meu Pai, tu és o guia de minha juventude?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 3, 5, 'Por acaso ele manterá [sua ira] para sempre?Ele a guardará para sempre? Eis que [isto] tu falas, porém tu tens feito tantas maldades quanto pudeste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 3, 6, 'Disse-me mais o SENHOR nos dias do rei Josias: Viste o que fez a rebelde Israel? Ela foi sobre todo monte alto e debaixo de toda árvore frondosa, e ali ela se prostituiu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 3, 7, 'E eu disse depois que ele fez tudo isto: Volta para mim; mas ela não voltou. E sua traiçoeira irmã Judá viu isto;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 3, 8, 'E eu vi, que por todas estas causas nas quais prostituiu a infiel Israel, eu a tinha mandado embora, e dado-lhe a carta de seu divórcio; porém a traiçoeira Judá sua irmã não temeu; ao contrário; ela também foi se prostituir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 3, 9, 'E aconteceu que foi pela leviandade de sua prostituição que a terra foi contaminada, e ela adulterou com a pedra e com a madeira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 3, 10, 'E mesmo com tudo isto, a traiçoeira, sua irmã Judá, não se converteu a mim de todo o seu coração, mas sim falsamente, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 3, 11, 'E disse-me o SENHOR: Israel mostrou-se mais justa em sua alma, mais do que a traiçoeira Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 3, 12, 'Vai, e proclama estas palavras ao norte, e diz: Volta-te, ó infiel Israel, diz o SENHOR; não farei cair minha ira sobre vós: pois sou misericordioso, diz o SENHOR; não guardarei [a ira] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 3, 13, 'Tão somente reconhece tua maldade, pois transgrediste contra o SENHOR teu Deus, e espalhaste teus caminhos aos estrangeiros debaixo de toda árvore frondosa, e não ouviste minha voz, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 3, 14, 'Convertei-vos, filhos infiéis, diz o SENHOR, pois sou vosso marido; e eu os tomarei um de uma cidade, e dois de uma família, e vos levarei a Sião;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 3, 15, 'E vos darei pastores conforme meu coração, que vos apascentem de conhecimento e de inteligência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 3, 16, 'E será que, quando vos multiplicardes e frutificardes na terra naqueles dias, diz o SENHOR, nunca mais dirão: Arca do pacto do SENHOR; nem virá ao pensamento, nem se lembrarão dela, nem a visitarão, nem será feita novamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 3, 17, 'Naquele tempo chamarão a Jerusalém: trono do SENHOR, e todas as nações se ajuntarão a ela no nome do SENHOR em Jerusalém; e nunca mais seguirão a teimosia de seu coração maligno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 3, 18, 'Naqueles tempos os da casa de Judá andarão com a casa de Israel, e virão juntamente da terra do norte à terra que eu fiz herdar a vossos pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 3, 19, 'Mas eu disse: Como te porei por filhos, e te darei a terra desejável, a rica propriedade dos exércitos das nações? E disse: tu me chamarás: Meu pai, e não te desviarás de detrás de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 3, 20, 'Porém, tal como a esposa trai o seu companheiro, assim traístes contra mim, ó casa de Israel, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 3, 21, 'Uma voz se ouve sobre os lugares altos: é o pranto das súplicas dos filhos de Israel; porque perverteram seu caminho, [e] se esqueceram do SENHOR seu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 3, 22, 'Convertei-vos, filhos rebeldes; eu sararei vossas rebeliões.Eis-nos aqui; chegamos a ti, porque tu és o SENHOR nosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 3, 23, 'Certamente [confiar] nos morros é inútil, na multidão dos montes; certamente a salvação de Israel está no SENHOR nosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 3, 24, 'Pois a vergonha consumiu o trabalho de nossos pais desde nossa juventude; suas ovelhas, suas vacas, seus filhos e suas filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 3, 25, 'Jazemos em nossa vergonha, e nossa humilhação nos cobre; porque pecamos contra o SENHOR nosso Deus, nós e nossos pais, desde nossa juventude até hoje; e não obedecemos a voz do SENHOR nosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 4, 1, 'Se te converteres, ó Israel,diz o SENHOR, converte-te a mim; e se tirares tuas abominações de diante de mim, não andarás mais sem rumo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 4, 2, 'E jurarás, dizendo, Vive o SENHOR, com verdade, com juízo, e com justiça; e nele as nações se bendirão, e nele se orgulharão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 4, 3, 'Porque assim diz o SENHOR aos homens de Judá e de Jerusalém: Fazei lavoura para vós, e não semeeis sobre espinhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 4, 4, 'Circuncidai-vos ao SENHOR, e tirai os prepúcios de vosso coração, ó homens de Judá e moradores de Jerusalém; para que minha ira não venha a sair como fogo, e se incendeie, e não haja quem apague, pela maldade de vossas obras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 4, 5, 'Anunciai em Judá, e fazei ouvir em Jerusalém, e dizei: Tocai trombeta na terra. Clamai em alta voz, e dizei: Ajuntai-vos, e entremos nas cidades fortes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 4, 6, 'Erguei bandeia para Sião, retirai-vos, não vos detenhais; porque eu trago um mal do norte, e grande destruição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 4, 7, 'O leão já subiu de seu refúgio, e o destruidor de nações já se partiu; ele saiu de seu lugar para pôr tua terra em assolação; tuas cidades serão destruídas, de modo que não haja [nelas] morador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 4, 8, 'Por isso vesti-vos de saco, lamentai e uivai; porque o ardor da ira do SENHOR não se desviou de nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 4, 9, 'E será naquele dia, diz o SENHOR, que o coração do rei e o coração dos príncipes desfalecerão; os sacerdotes ficarão pasmos, e os profetas se maravilharão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 4, 10, 'Então eu disse: Ah, Senhor DEUS! Verdadeiramente enganaste grandemente a este povo e a Jerusalém, dizendo: Tereis paz; porém a espada chega até a alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 4, 11, 'Naquele tempo se dirá a este povo e a Jerusalém: Um vento seco dos lugares altos do deserto [veio] ao caminho da filha do meu povo; não para padejar, nem para limpar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 4, 12, 'Um vento forte demais para estas coisas virá de mim; agora também eu pronunciarei juízos contra eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 4, 13, 'Eis que ele virá subindo como as nuvens, e suas carruagens como o redemoinho de vento; seus cavalos serão mais velozes que as águias;Ai de nós, porque somos assolados!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 4, 14, 'Lava teu coração da maldade para que sejas salva; ó Jerusalém! Até quando deixarás os teus meus pensamentos permanecerem em meio a ti?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 4, 15, 'Porque uma voz se anuncia desde Dã, e fala de calamidade desde o monte de Efraim:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 4, 16, 'Disto mencionai às nações: eis aqui! Proclamai contra Jerusalém: Guardas vêm de uma terra remota, e levantam sua voz contra as cidades de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 4, 17, 'Como guardas dos campos, assim eles estão ao redor contra ela; pois ela se rebelou contra mim,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 4, 18, 'Teu caminho e teus atos te causaram estas coisas; esta é tua maldade, tão amarga, que chega ao teu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 4, 19, 'Ai minhas entranhas, minhas entranhas! Estou com grandes dores nas paredes do meu coração; meu coração se inquieta, não consigo me calar; porque tu, ó alma minha, ouves o som da trombeta, o clamor da guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 4, 20, 'Destruição sobre destruição se anuncia, pois toda a terra já está arruinada; de repente foram destruídas minhas tendas, num instante minhas cortinas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 4, 21, 'Até quando verei a bandeira, [e] ouvirei a voz da trombeta?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 4, 22, 'De fato meu povo está louco, já não me conhecem; são filhos tolos, sem entendimento; são “sábios” para fazer o mal, mas para fazer o bem nada sabem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 4, 23, 'Vi a terra, e eis que estava sem forma e vazia; e [vi] os céus, e não tinham sua luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 4, 24, 'Vi os montes, e eis que estavam tremendo; e todos os morros se sacudiam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 4, 25, 'Vi, e eis que nenhum homem havia; e todas as aves do céu tinham fugido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 4, 26, 'Vi, e eis que a terra fértil [tinha se tornado] um deserto, e todas as suas cidades foram derrubadas, por causa do SENHOR, por causa do ardor de sua ira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 4, 27, 'Porque assim diz o SENHOR: Toda esta terra será assolada; porém não [a] destruirei por completo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 4, 28, 'Por isto a terra lamentará, e os céus acima se tornarão negros; porque [assim] falei, [assim] o propus, e não me arrependerei, nem desviarei disso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 4, 29, 'Do ruído dos cavaleiros e dos flecheiros, [os moradores de] todas as cidades fugirão; entrarão nos bosques, e subirão em penhascos; todas as cidades ficarão abandonadas, e não haverá nelas morador algum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 4, 30, 'E que farás tu, ó assolada? Ainda que te vistas de vermelho, ainda que te adornes com ornamentos de ouro, ainda que pintes teus olhos, em vão te enfeitarias; os [teus] amantes te desprezam, [e] buscarão [matar] a tua alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 4, 31, 'Porque ouço uma voz, como de mulher que está de parto, uma angústia como de parto de primeiro filho; é a voz da filha de Sião, que lamenta e estende suas mãos, [dizendo] : Ai de mim agora! Pois minha alma desmaia por causa dos assassinos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 5, 1, 'Correi pelas ruas de Jerusalém, e olhai agora, e informai-vos, e buscai em suas praças, [para ver] se achais algum homem, se há alguém que faça juízo, que busque a verdade; e eu a perdoarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 5, 2, 'E ainda que digam: Vive o SENHOR; contudo juram falsamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 5, 3, 'Ah SENHOR, por acaso teus olhos não [enxergam] a verdade? Tu os feriste, mas não lhes doeu; tu os consumiste, mas não aceitaram receber correção; endureceram seus rostos mais que rocha; não quiseram se converter.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 5, 4, 'Eu porém disse: Certamente eles são pobres; enlouqueceram, pois não conhecem o caminho do SENHOR, o juízo de seu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 5, 5, 'Irei aos grandes, e falarei com eles; porque eles conhecem o caminho do SENHOR, o juízo de seu Deus.Porém eles também quebraram o jugo; [também] romperam as amarras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 5, 6, 'Por isso um leão do bosque os ferirá; um lobo do deserto os destruirá; um leopardo vigiará sobre suas cidades; qualquer um que delas sair, será despedaçado; pois suas transgressões se multiplicaram, foram numerosas suas infidelidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 5, 7, 'Como te perdoaria por isto? Teus filhos me deixaram, e juram pelo que não é Deus. Eu os saciei, porém eles adulteraram, e se aglomeraram em casa de prostitutas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 5, 8, '[Como] cavalos bem alimentados, levantam-se pela manhã; cada um relinchava à mulher de seu próximo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 5, 9, 'Não teria eu de fazer visitação sobre isto?diz o SENHOR. De uma nação como esta não vingaria minha alma?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 5, 10, 'Subi seus muros, e destruí; mas não destruais por completo. Tirai os ramos de seus muros, porque não pertencem ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 5, 11, 'Pois a casa de Israel e a casa de Judá traíram enganosamente contra mim,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 5, 12, 'Negaram ao SENHOR, e disseram: Não é ele; não virá mal sobre nós; não veremos espada, nem fome;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 5, 13, 'e até os profetas serão [como] o vento, pois a palavra não está neles; assim acontecerá a eles mesmos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 5, 14, 'Portanto assim diz o SENHOR Deus dos exércitos: Visto que falastes esta palavra, eis que tornarei minhas palavras em tua boca em fogo, e a este povo será lenha; e [o fogo] os consumirá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 5, 15, 'Eis que trarei sobre vós uma nação de longe, ó casa de Israel,diz o SENHOR; uma nação forte, nação bastante antiga; uma nação cuja língua não saberás, e o que falarem não entenderás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 5, 16, 'Sua aljava é como uma sepultura aberta; todos eles são poderosos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 5, 17, 'E comerão tua colheita e teu pão, que teus filhos e tuas filhas comeriam; comerão tuas ovelhas e tuas vacas, comerão tuas vides e tuas figueiras; e derrubarão por meio da espada tuas cidades fortes em que confias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 5, 18, 'Porém naqueles dias, diz o SENHOR, não vos acabarei por completo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 5, 19, 'E será que quando disserdes: Por que o SENHOR nosso Deus fez conosco todas estas coisas? Então lhes dirás: Assim como vós me abandonastes e servistes a deuses estrangeiros em vossa terra, assim também servireis a estrangeiros numa terra que não é vossa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 5, 20, 'Anunciai isto na casa de Jacó, e fazei com que isto se ouça em Judá, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 5, 21, 'Ouvi agora isto, ó povo tolo e insensato, que têm olhos e não veem, que têm ouvidos e não ouvem:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 5, 22, 'Por acaso não me temereis?diz o SENHOR; Não vos assombrareis perante mim, que pus a areia por limite ao mar por ordenança eterna, a qual não passará? Ainda que se levantarem suas ondas, mas elas não prevalecerão; ainda que bramem, não a passarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 5, 23, 'Porém este povo tem coração teimoso e rebelde; viraram-se, e se foram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 5, 24, 'Nem sequer dizem em seu coração: Temamos agora ao SENHOR nosso Deus, que dá chuva temporã e tardia em seu tempo; os tempos estabelecidos da ceifa ele nos guarda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 5, 25, 'Vossas perversidades têm desviado estas coisas; e vossos pecados afastaram de vós o bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 5, 26, 'Porque foram achados perversos em meu povo; eles espiavam como quem põe laços; puseram armadilhas para prenderem homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 5, 27, 'Como uma gaiola cheia de pássaros, assim estão suas casas cheias de engano: assim eles se fizeram grandes e ricos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 5, 28, 'Eles se engordaram e ficaram lustrosos, e ultrapassaram os limites das obras do mal; não julgam causa nenhuma, [nem sequer] a causa do órfão; porém fizeram-se prósperos; nem julgam o direito dos necessitados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 5, 29, 'Por acaso eu não [os] puniria por causa disto? Diz o SENHOR; e de tal nação não se vingará minha alma?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 5, 30, 'Uma coisa espantosa e horrível está sendo feita na terra:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 5, 31, 'Os profetas profetizam falsamente, e os sacerdotes exercem liderança por suas próprias mãos; e meu povo assim o quer. Mas o que fareis quando isto chegar ao fim?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 6, 1, 'Fugi, ó filhos de Benjamim, do meio de Jerusalém; e tocai trombeta em Tecoa, e levantai um sinal de fumaça sobre Bete-Haquerém; porque do norte já se vê o desastre e grande destruição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 6, 2, 'Destruirei a filha de Sião [ainda que seja] formosa e delicada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 6, 3, 'A ela virão pastores com seus rebanhos; levantarão contra ela tendas ao redor; [e] cada um apascentará em seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 6, 4, 'Preparai guerra contra ela; levantai-vos e subamos até o meio-dia! Ai de nós! que vai caindo já o dia, que as sombras da tarde já estão se estendendo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 6, 5, 'Levantai-vos, e subamos de noite, e destruamos seus palácios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 6, 6, 'Porque assim diz o SENHOR dos exércitos: Cortai árvores, e levantai cercos junto a Jerusalém; esta é a cidade que tem de ser punida; opressão há no meio dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 6, 7, 'Tal como a fonte jorra suas águas, assim também ela constantemente jorra sua malícia; violência e destruição se ouve nela; continuamente há enfermidade e feridas perante mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 6, 8, 'Corrige-te, Jerusalém, para que minha alma não se afaste de ti, para que eu não te torne desolada, uma terra não habitada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 6, 9, 'Assim diz o SENHOR dos exércitos: Sacudirão por completo o restante de Israel tal como a vide; volta tua mão aos cestos como alguém que colhe uvas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 6, 10, 'A quem falarei e testemunharei, para que ouçam? Eis que que seus ouvidos são incircuncisos, e não podem escutar; eis que a palavra do SENHOR lhes é coisa vergonhosa, não gostam dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 6, 11, 'Por isso estou cheio dá fúria do SENHOR, [e] cansado estou de retê [-la] ; eu a derramarei sobre os meninos pelas ruas, e sobre a reunião dos jovens juntamente; porque até o marido com a mulher serão presos, [e] o velho com o cheio de dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 6, 12, 'E suas casas passarão a ser de outros, suas propriedades e juntamente suas mulheres; porque estenderei minha mão contra os moradores da terra, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 6, 13, 'Porque desde o menor deles até o maior deles, cada um deseja com ganância; e desde o profeta até o sacerdote, todos agem com falsidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 6, 14, 'E curam a ferida da filha de meu povo apenas superficialmente, dizendo, Paz, paz; sem que haja paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 6, 15, 'Eles se envergonham de fazerem abominação? Não, não se envergonham de maneira nenhuma, nem sequer sabem ter vergonha. Por isso cairão entre os que caem; tropeçarão quando eu os visitar, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 6, 16, 'Assim diz o SENHOR: Ficai parados nos caminhos, e vede, e perguntai pelas veredas antigas, qual é o bom caminho, e andai por ele; então achareis descanso para vossa alma. Mas disseram: Não andaremos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 6, 17, 'Também pus vigilantes sobre vós, que dissessem: Prestai atenção à voz da trombeta. Mas eles disseram: Não prestaremos atenção.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 6, 18, 'Portanto ouvi, ó nações, e saiba disto, o multidão que nelas está;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 6, 19, 'Ouve tu, ó terra: Eis que eu trarei mal sobre este povo: o fruto de seus pensamentos; pois não dão atenção a minhas palavras, e rejeitam a minha lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 6, 20, 'Afinal, para que vem a mim o incenso de Sabá, e a boa cana aromática de uma terra distante? Vossos holocaustosnão [me] são aceitáveis, nem vossos sacrifícios me são agradáveis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 6, 21, 'Portanto assim diz o SENHOR: Eis que porei tropeços a este povo, e cairão neles juntamente os pais e os filhos; o vizinho e seu companheiro perecerão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 6, 22, 'Assim diz o SENHOR: Eis que vem um povo da terra do norte; e uma grande nação se levantará dos confins da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 6, 23, 'Eles trarão arco e lança; são cruéis, que não terão misericórdia; a voz deles rugirá como o mar, e sobre cavalo cavalgarão, como homens dispostos para a guerra contra ti, ó filha de Sião.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 6, 24, 'Nós ouvimos a fama deles, e nossas mãos perderam a força; fomos tomados pela angústia, [e] dor como de mulher no parto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 6, 25, 'Não saiais ao campo, nem andeis pelo caminho; porque a espada do inimigo [e] o terror está ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 6, 26, 'Tu, filha de meu povo, veste-te de saco, e revolve-te em cinza; chora de luto [como] por um filho único, pranto de amarguras; porque logo virá sobre nós o destruidor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 6, 27, 'Eu te pus por avaliador e por fortaleza entre meu povo, para que reconheças, e examines o caminho deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 6, 28, 'Todos eles são os mais teimosos rebeldes, que vivem enganando; são [duros como] cobre e ferro: todos eles são corruptos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 6, 29, 'O fole já se queimou, o chumbo já se consumiu pelo fogo; em vão é feita a fundição, pois os maus não são arrancados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 6, 30, 'Eles são chamados prata rejeitada, porque o SENHOR os rejeitou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 1, 'Palavra que veio do SENHOR a Jeremias, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 2, 'Põe-te à porta da casa do SENHOR, e clama ali esta palavra, e dize: Ouvi palavra do SENHOR, toda Judá, vós que entrais por estas portas para adorar ao SENHOR!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 3, 'Assim diz o SENHOR dos exércitos, Deus de Israel: Melhorai vossos caminhos e vossos atos, e eu vos farei habitar neste lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 4, 'Não confieis em palavras falsas, que dizem: Templo do SENHOR! Templo do SENHOR! Este é o templo do SENHOR!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 5, 'Mas se verdadeiramente melhorardes vossos caminhos e vossas obras; se verdadeiramente fizerdes justiça entre o homem e seu próximo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 6, 'E não oprimirdes ao estrangeiro que peregrina entre vós, ao órfão, e à viúva, nem derramardes sangue inocente neste lugar, nem seguirdes deuses estrangeiros para vosso mal;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 7, 'Eu vos farei morar neste lugar, na terra que dei a vossos pais desde os tempos antigos para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 8, 'Eis que vós os confiais em palavras falsas, que não têm proveito algum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 9, 'Por acaso furtareis, matareis, e adulterareis, e jurareis falsamente, e queimareis incenso a Baal, e andareis atrás de deuses estrangeiros, a quem não conheceis,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 10, 'E [então] vireis e vos poreis perante mim nesta casa , que se chama pelo meu nome, e direis: Libertos somos, para fazer todas estas abominações?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 11, 'Por acaso esta casa, que se chama pelo meu nome, é uma caverna de assaltantes perante vossos olhos? Eis que também vi [isso] , diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 12, 'Porém ide agora a meu lugar, que era em Siló, onde fiz habitar meu nome no princípio; e vede o que lhe fiz pela maldade do meu povo Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 13, 'Portanto agora, visto que vós tendes feito todas estas obras, diz o SENHOR, e vos falei, insistindo em falar, mas não ouvistes, e eu os chamei, mas não respondestes;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 14, 'Farei também a esta casa, que se chama pelo meu nome, em que vós confiais, e a este lugar que dei a vós e a vossos pais, tal como fiz a Siló:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 15, 'E eu vos lançarei fora de minha presença, tal como lancei a todos os vossos irmãos, toda a geração de Efraim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 16, 'Por isso não ores tu por este povo, nem levantes por eles clamor nem oração, nem rogues a mim, pois eu não te ouvirei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 17, 'Não vês o que eles costumam fazer nas cidades de Judá e nas ruas de Jerusalém?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 18, 'Os filhos coletam a lenha, e os pais acendem o fogo, e as mulheres amassam a massa, para fazerem bolos à rainha dos céus e dedicarem ofertas de bebidas a deuses estrangeiros, para me provocarem à ira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 19, 'Por acaso eles me provocam à ira?diz o SENHOR, eles não [acabam provocando mais] a si mesmos, para vergonha de seus próprios rostos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 20, 'Por isso assim diz o Senhor DEUS: Eis que que minha ira e meu furor serão derramados sobre este lugar: sobre os homens, sobre os animais, sobre as árvores do campo, e sobre os frutos da terra; e se acenderá, e não se apagará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 21, 'Assim diz o SENHOR dos exércitos, Deus de Israel: Acrescentai os vossos holocaustos aos vossos sacrifícios, e comei carne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 22, 'Pois não falei a vossos pais, nem lhes mandei, no dia em que os tirei da terra do Egito, coisa alguma sobre holocaustos ou sacrifícios;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 23, 'porém isto lhes mandei, dizendo: Escutai a minha voz, e eu serei vosso Deus, e vós sereis meu povo; e andai em todo o caminho que eu vos mandar, para que o bem vos aconteça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 24, 'Mas eles não ouviram, nem inclinaram seus ouvidos; ao invés disso, caminharam em [seus próprios] conselhos, na teimosia de seu coração maligno, e foram para trás, e não para frente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 25, 'Desde o dia em que vossos pais saíram da terra do Egito até hoje, eu vos enviei a todos os meus servos os profetas, e enviando-os dia após dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 26, 'Mas eles não me ouviram, nem inclinaram seu ouvidos; ao invés disso, teimaram ainda mais, e fizeram pior que seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 27, 'Por isso tu lhes dirás todas estas palavras, mas eles não te ouvirão; e tu os chamarás, mas eles não te responderão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 28, 'Então tu lhes dirás: Esta é a nação que não escutou a voz do SENHOR seu Deus, nem aceitou correção; a verdade pereceu, e foi cortada de suas bocas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 29, 'Tosquia o teu cabelo, e lança-o fora, e levanta pranto sobre os lugares altos; porque o SENHOR tem rejeitado e abandonado a nação que causou sua ira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 30, 'Porque os filhos de Judá fizeram o mal perante meus olhos, diz o SENHOR; puseram suas abominações na casa que se chama pelo meu nome, para contaminá-la.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 31, 'E edificaram os altos de Tofete, que ficam no vale do filho de Hinom, para queimarem no fogo seus filhos e suas filhas, o que eu nunca mandei, nem pensei em meu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 32, 'Por isso eis que virão dias, diz o SENHOR, que não se dirá mais Tofete, nem Vale do filho de Hinom, mas sim Vale da Matança; e serão enterrados em Tofete, por não haver lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 33, 'E os cadáveres deste povo serão para comida das aves dos céus e dos animais da terra; e ninguém os espantará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 7, 34, 'E farei cessar das cidades de Judá e da ruas de Jerusalém a voz de júbilo e voz de alegria, voz de noivo e voz de noiva; porque a terra se tornará desolação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 8, 1, 'Naquele tempo, diz o SENHOR, tirarão os ossos dos reis de Judá, e os ossos de seus príncipes, e os ossos dos sacerdotes, e os ossos dos profetas, e os ossos dos moradores de Jerusalém, para fora de suas sepulturas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 8, 2, 'E os estenderão ao sol, à lua, e a todo o exército do céu, a quem amaram, e a quem serviram, e atrás de quem se foram, e a quem buscaram, e a quem se prostraram. Não serão recolhidos nem sepultados: serão por esterco sobre a superfície da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 8, 3, 'E a morte será preferida à vida por todos os restantes que restarem desta má geração, que restarem em todos os lugares onde eu os lancei, diz o SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 8, 4, 'Dize-lhes também: Assim diz o SENHOR: Por acaso os que caem não se levantam? Os que se desviam, não voltam [ao caminho] ?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 8, 5, 'Então por que este povo de Jerusalém continuam se desviando permanentemente? Eles se mantêm no engano, não querem voltar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 8, 6, 'Escutei e ouvi; não falam daquilo que é correto, ninguém há que se arrependa de sua maldade, dizendo: O que é que fiz? Cada um se virou ao seu percurso, tal como cavalo que corre com ímpeto para a batalha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 8, 7, 'Até a cegonha no céu conhece seus tempos certos, e a rolinha, o grou e a andorinha dão atenção ao tempo de sua vinda; mas meu povo não conhece o juízo do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 8, 8, 'Como, pois, dizeis: Nós somos sábios, e a lei do SENHOR está conosco? Certamente eis que a falsa pena dos escribas tem se feito em mentira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 8, 9, 'Os sábios serão envergonhados, espantados, e presos; eis que rejeitaram a palavra do SENHOR; que sabedoria, então, eles têm?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 8, 10, 'Por isso darei suas mulheres a outros, [e] suas propriedades a quem as possuam: pois desde o menor até o maior, cada um se enche de avareza, desde o profeta até o sacerdote, todos agem com falsidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 8, 11, 'E curam a ferida da filha de meu povo apenas superficialmente, dizendo: Paz, paz; sem que haja paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 8, 12, 'Por acaso eles se envergonham de terem feito abominação? Não, eles não se envergonharam; eles nem sequer sabem o que é ter vergonha; por isso cairão entre os que caírem, tropeçarão no tempo em que eu os castigar, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 8, 13, 'Certamente eu os apanharei,diz o SENHOR. Não haverá uvas na vide, nem figos na figueira, e [até] a folha cairá; e aquilo que lhes dei passará deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 8, 14, 'Por que [ainda] estamos sentados? Ajuntai-vos, e entremos nas cidades fortes; e ali pereçamos: pois o SENHOR nosso Deus tem nos matado, e nos deu a beber bebida de fel, porque pecamos contra o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 8, 15, 'Esperávamos paz, mas nada de bom houve; [esperávamos] tempo de cura, e eis aqui terror.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 8, 16, 'Desde Dã se ouve o ronco de seus cavalos; toda a terra treme pelo som do relinchar de seus fortes; e eles vêm e devoram a terra e sua abundância, a cidade e seus moradores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 8, 17, 'Porque eis que eu envio entre vós serpentes, [e] cobras venenosas, contra as quais não há encantamento; e elas vos morderão, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 8, 18, 'Até meu consolo está em tristeza; meu coração desfalece em mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 8, 19, 'Eis a voz do clamor da filha de meu povo, desde uma da terra distante: Por acaso não está o SENHOR em Sião? Não está nela o seu rei? Por que me provocaram à ira com suas imagens de escultura, com coisas estrangeiras inúteis?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 8, 20, 'Passou a ceifa, acabou-se o verão, e nós não fomos salvos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 8, 21, 'Quebrantado estou pelo quebrantamento da filha de meu povo; estou de luto, fui tomado pelo assombro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 8, 22, 'Por acaso não há bálsamo em Gileade, ou não há ali médico? Então por que não houve cura para a filha de meu povo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 9, 1, 'Ah, se minha cabeça se tornasse em águas, e meus olhos em um manancial de águas! Então eu choraria dia e noite pelos mortos da filha de meu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 9, 2, 'Ah, se houvesse para mim no deserto uma hospedaria para caminhantes! Então eu deixaria o meu povo, e me afastaria deles; pois todos eles são adúlteros, são um bando de traiçoeiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 9, 3, 'Eles estendem suas línguas, como [se] lhes fossem arcos, para atirarem mentira; e se fortaleceram na terra, mas não por meio da verdade; porque se avançam de mal em mal, e não me conhecem, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 9, 4, 'Guardai-vos cada um de seu amigo, nem em irmão algum tende confiança: porque todo irmão só faz enganar, e todo amigo anda com falsidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 9, 5, 'E cada um engana a seu amigo, e não falam a verdade; ensinaram sua língua a falar mentira, e agem perversamente até se cansarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 9, 6, 'Tua habitação é em meio ao engano; por meio do engano se negam a me conhecer,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 9, 7, 'Portanto assim diz o SENHOR dos exércitos: Eis que que eu os fundirei, e os provarei; pois de que [outra maneira] agiria eu com a filha de meu povo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 9, 8, 'A língua deles é uma flecha mortífera, que fala engano; com sua boca fala paz com seu próximo, mas em seu interior lhe arma ciladas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 9, 9, 'Por acaso eu não os puniria por estas coisas? Diz o SENHOR. Por acaso minha alma não se vingaria de tal nação?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 9, 10, 'Sobre os montes levantarei choro e pranto, e lamentação as moradas do deserto; porque foram desoladas até não haver quem [por ali] passe, nem [ali] se ouve bramido de gado; desde as aves do céu e até os animais da terra fugiram, e foram embora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 9, 11, 'E tornarei Jerusalém em amontoados [de pedras] ,para morada de chacais; e tornarei as cidades de Judá em ruínas, de modo que não haja morador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 9, 12, 'Quem é homem sábio, que entenda isto? E a quem falou a boca do SENHOR, para que possa anunciá-lo? Por que razão a terra pereceu, queimada como deserto, de modo que não há quem [nela] passe?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 9, 13, 'E disse o SENHOR: Foi porque abandonaram minha lei, que dei diante deles, nem deram ouvidos a minha voz, nem caminharam conforme a ela;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 9, 14, 'Ao invés disso, eles seguiram atrás da teimosia de seu coração, e atrás dos Baalins, que seus pais lhes ensinaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 9, 15, 'Por isso assim diz o SENHOR dos exércitos, Deus de Israel: Eis que a este povo eu lhes darei de comer absinto, e lhes darei de beber água de fel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 9, 16, 'E os espalharei entre nações que nem eles, nem seus pais conheceram; e mandarei espada atrás deles, até que eu os acabe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 9, 17, 'Assim diz o SENHOR dos exércitos: Considerai, e chamai carpideiras, que venham; e enviai as mais hábeis, que venham:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 9, 18, 'E se apressem, e levantem pranto sobre nós, e desfaçam-se nossos olhos em lágrimas, e nossas pálpebras se destilem em águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 9, 19, 'Porque uma voz de pranto foi ouvida de Sião: Como fomos destruídos! Nós nos tornamos muito envergonhados, por termos deixado a terra, por nossas moradas terem sido arruinadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 9, 20, 'Ouvi pois, vós mulheres, a palavra do SENHOR, e vossos ouvidos recebam a palavra de sua boca; e ensinai pranto a vossas filhas, e cada uma lamentação a sua companheira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 9, 21, 'Porque a morte subiu a nossas janelas, [e] entrou em nossos palácios; para arrancar os meninos das ruas, os rapazes das praças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 9, 22, 'Fala: Assim disse o SENHOR: Os cadáveres dos homens cairão como esterco sobre a face do campo, e como espigas de cereal atrás do ceifeiro, que não há quem as recolha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 9, 23, 'Assim diz o SENHOR: Não se orgulhe o sábio em sua sabedoria, nem o valente se orgulhe em sua valentia, nem o rico se orgulhe em suas riquezas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 9, 24, 'Mas aquele que se orgulhar, orgulhe-se nisto: em me entender e me conhecer, que eu sou o SENHOR, que faço bondade, juízo, e justiça na terra; porque destas coisas eu me agrado,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 9, 25, 'Eis que vêm dias, diz o SENHOR, em que castigarei todo circunciso e todo incircunciso:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 9, 26, 'A Egito, a Judá, a Edom, aos filhos de Amom e de Moabe, e a todos os dos cantos mais distantes, que moram no deserto; pois todas as nações são incircuncisas; mas toda a casa de Israel é incircuncisa no coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 10, 1, 'Ouvi a palavra que o SENHOR fala sobre vós, ó casa de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 10, 2, 'Assim diz o SENHOR: Não aprendais o caminho das nações, nem vos espanteis dos sinais do céu; ainda que as nações as temam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 10, 3, 'Porque as ordenanças dos povos são inúteis; pois cortam madeira do bosque, obra de mãos de artífice, com machado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 10, 4, 'Com prata e ouro a enfeitam; com pregos e martelo a firmam, para que não se abale.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 10, 5, 'São como espantalhos numa plantação, não podem falar; têm que ser levados, pois não podem andar. Não tenhais temor deles; pois nem podem fazer o mal, nem neles há [capacidade de fazer] o bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 10, 6, 'Pois ninguém há semelhante a ti, SENHOR! Grande és tu, e grande é teu nome em poder!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 10, 7, 'Quem não temeria a ti, ó Rei das nações? Porque a ti pertence [o temor] ; porque entre todos os sábios das nações, e em todos seus reinos, não há semelhante a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 10, 8, 'E juntamente se tornaram irracionais e tolos. Ensino inútil é o [ídolo] de madeira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 10, 9, 'Trazem prata estendida de Társis, e ouro de Ufaz; [para] trabalho do artífice, e das mãos do fundidor; eles os vestem de azul celeste e de púrpura; todos eles são obra de [trabalhadores] habilidosos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 10, 10, 'Mas o SENHOR Deus é a verdade; ele é Deus vivo e o Rei eterno; a terra treme pela sua ira, e as nações não podem suportar sua fúria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 10, 11, 'Assim lhes direis: Os deuses que não fizeram os céus nem a terra perecerão da terra e de debaixo deste céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 10, 12, '[Mas o SENHOR] é aquele que fez a terra com seu poder, que preparou o mundo com sua sabedoria, e estendeu os céus com seu entendimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 10, 13, 'Quando ele pronuncia sua voz, [logo] há ruído de águas no céu, e faz subir vapores dos confins da terra; faz os relâmpagos com a chuva, e faz sair o vento de seus tesouros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 10, 14, 'Todo homem se tornou irracional e sem conhecimento; envergonha-se todo fundidor de imagem de escultura, pois sua imagem fundida é uma mentira, e nelas não há espírito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 10, 15, 'Elas são inúteis, obras de engano; no tempo de sua punição, virão a perecer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 10, 16, 'A Porção de Jacó não é como eles; porque ele é o Formador de tudo, e Israel é a tribo de sua herança; EU-SOU dos exércitos é o seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 10, 17, 'Recolhe tuas mercadorias da terra; tu que habitas em cerco,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 10, 18, 'Porque assim diz o SENHOR: Eis que desta vez lançarei como que por uma funda aos moradores da terra; e eu os oprimirei, de modo que sejam achados [em opressão] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 10, 19, 'Ai de mim, por causa do meu quebrantamento! Minha ferida [me] causa grande dor. E eu havia dito: Isto de fato é uma enfermidade, e terei que suportá-la.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 10, 20, 'Minha tenda está destruída, e todas as minhas cordas arrebentadas; meus filhos saíram [de perto] de mim, e nenhum deles há; ninguém há que estenda minha tenda, nem que levante minhas cortinas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 10, 21, 'Porque os pastores se tornaram irracionais, e não buscaram ao SENHOR; por isso não agiram prudentemente, e todo o seu rebanho se dispersou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 10, 22, 'Eis que vem uma voz de aviso, e um grande tremor da terra do norte; para tornar em desolação as cidades de Judá, em morada de chacais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 10, 23, 'Eu sei, SENHOR, que não pertence ao homem o seu caminho, nem ao homem que anda a direção de seus passos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 10, 24, 'Corrige-me, SENHOR, porém com moderação; não em tua ira, para que não me destruas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 10, 25, 'Derrama tua ira sobre as nações que não te conhecem, e sobre os povos que não invocam o teu nome; pois devoraram a Jacó; eles o devoraram, consumiram e assolaram sua morada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 11, 1, 'Palavra que veio do SENHOR, a Jeremias, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 11, 2, 'Ouvi as palavras deste pacto, e falai aos homens de Judá, e aos moradores de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 11, 3, 'Dize-lhes, pois: Assim diz o SENHOR, Deus de Israel: Maldito o homem que não ouvir as palavras deste pacto,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 11, 4, 'Que mandei a vossos pais no dia que os tirei da terra do Egito, do forno de ferro, dizendo: Ouvi a minha voz, e as fazei conforme a tudo quanto eu vos mando; então vós sereis meu povo, e eu serei vosso Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 11, 5, 'Para que eu confirme o juramento que fiz a vossos pais, que lhes daria uma terra em que mana leite e mel, tal como hoje.E eu respondi, e disse: Amém, SENHOR!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 11, 6, 'E disse-me o SENHOR: Proclama todas estas palavras nas cidades de Judá e nas ruas de Jerusalém, dizendo: Ouvi as palavras deste pacto, e praticai-as;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 11, 7, 'Porque insistentemente adverti a vossos pais o dia que eu os tirei da terra do Egito até o dia de hoje, repetidamente advertindo, dizendo: Ouvi minha voz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 11, 8, 'Porém não ouviram, nem inclinaram seus ouvidos; ao invés disso, seguiram cada um a teimosia de seu coração maligno. Por isso trouxe sobre eles todas as palavras deste pacto, que mandei que cumprissem, mas não cumpriram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 11, 9, 'E disse-me o SENHOR: Achou-se conspiração entre os homens de Judá, e entre os moradores de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 11, 10, 'Voltaram às maldades de seus primeiros pais, que se recusaram a ouvir minhas palavras; ao invés disso, eles seguiram deuses estrangeiros, para lhes servirem; a casa de Israel e a casa de Judá violaram meu pacto, que eu tinha feito com seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 11, 11, 'Portanto, assim diz o SENHOR: Eis que trarei sobre eles calamidade, da qual não poderão escapar; e clamarão a mim, mas eu não os ouvirei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 11, 12, 'Então as cidades de Judá e os moradores de Jerusalém irão, e clamarão aos deuses a quem queimam incensos; porém de maneira nenhuma poderão os salvar no tempo de sua calamidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 11, 13, 'Porque teus deuses foram tão numerosos quanto tuas cidades, ó Judá; e tão numerosos quanto tuas ruas, ó Jerusalém, vós pusestes altares da vergonha, altares para queimar incensos a Baal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 11, 14, 'Tu, pois, não ores por este povo, nem levantes por eles clamor nem oração; porque eu não ouvirei no dia em que clamarem a mim em meio a calamidade deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 11, 15, 'Que [direito] tem minha amada em minha casa, visto que muitos têm feito tão grandes abominações? Podem carnes “santificadas” te livrar, de modo que te alegras com tua maldade?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 11, 16, 'O SENHOR chamava o teu nome de Oliveira verde, formosa de belos frutos. [Porém agora] ,à voz de grande tumulto, ele acendeu fogo sobre ela, e seus ramos foram quebrados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 11, 17, 'Pois o SENHOR dos exércitos, que te plantou, pronunciou calamidade contra ti, por causa da maldade da casa de Israel e da casa de Judá, que fizeram entre si mesmos, para me provocarem à ira queimando incenso a Baal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 11, 18, 'E o SENHOR me fez saber, e conhecer; então tu me fizeste ver suas ações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 11, 19, 'E eu estava como cordeiro manso, que levam para degolar, pois não entendia que tramavam planos contra mim, dizendo: Destruamos a árvore com seu fruto, e o cortemos da terra dos viventes, e não haja mais lembrança de seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 11, 20, 'Mas, ó SENHOR dos exércitos, justo juiz, que provas os sentimentos e pensamentos, veja eu tua vingança deles; porque a ti mostrei minha causa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 11, 21, 'Portanto assim diz o SENHOR quanto aos homens de Anatote, que buscam [matar] tua alma, dizendo: Não profetizes em nome do SENHOR, para que não morras por meio de nossas mãos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 11, 22, 'Portanto assim diz o SENHOR dos exércitos: Eis que eu os punirei; os rapazes morrerão a espada; seus filhos e suas filhas morrerão de fome;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 11, 23, 'E não restará sobrevivente deles, pois eu trarei calamidade sobre os homens de Anatote, [no] ano em que serão punidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 12, 1, 'Justo és tu, SENHOR, mesmo quando eu discuto contigo; falarei, porém, de juízos contigo. Por que o caminho dos perversos prospera, e todos os que agem enganosamente têm boa vida?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 12, 2, 'Tu os plantaste, e firmaram raízes; eles progridem, e dão fruto; tu estás perto de suas bocas, porém longe de seus sentimentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 12, 3, 'Mas tu, SENHOR, me conheces; tu me vês, e provas o meu coração para contigo. Arranca-os como a ovelhas para o matadouro, e reserva-os para o dia da matança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 12, 4, 'Até quando lamentará a terra, e a erva de todo o campo ficará seca? Pela maldade dos que nela habitam, os animais e as aves perecem; porque dizem: Ele não verá ele nosso fim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 12, 5, 'Se ao correres com os que estão a pé, eles te cansam, como competirás com os cavalos? E se [somente] em terra de paz te sentes seguro, como agirás tu nos matagais junto ao Jordão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 12, 6, 'Porque até teus irmãos e a casa de teu pai passaram a agir traiçoeiramente contra ti, até eles gritaram atrás de ti. Não creias neles, quando te falarem coisas boas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 12, 7, 'Deixei minha casa, abandonei minha herança, entreguei a amada de minha alma nas mãos de seus inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 12, 8, 'Minha herança se tornou para mim como um leão na floresta: ela levantou sua voz contra mim; por isso que eu a odeio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 12, 9, 'Não é minha herança para mim uma ave de rapina de muitas cores? Não estão contra ela aves de rapina ao redor? Vinde, ajuntai-vos, todas os animais do campo, vinde para devorá-la.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 12, 10, 'Muitos pastores destruíram minha vinha, pisaram meu campo; tornaram meu campo desejado em um deserto devastado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 12, 11, 'Tornaram-no em desolação, e lamenta a mim, desolado; toda a terra está desolada, porque ninguém há que pense [nisso] no coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 12, 12, 'Sobre todos os lugares altos do deserto vieram destruidores; porque a espada do SENHOR devora desde um extremo da terra até o outro extremo; não haverá paz para nenhuma carne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 12, 13, 'Semearam trigo, e ceifarão espinhos; cansaram-se, mas não tiveram proveito algum. Envergonhai-vos de vossos frutos, por causa da ardente ira do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 12, 14, 'Assim diz o SENHOR quanto a todos os meus maus vizinhos, que tocam a minha herança, a qual dei por herança a meu povo Israel: Eis que eu os arrancarei de sua terra, e arrancarei a casa de Judá do meio deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 12, 15, 'E será que, depois de os arrancar, voltarei, terei compaixão deles, e os farei voltar cada um à sua herança, e cada um à sua terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 12, 16, 'E será que, se cuidadosamente aprenderem os caminhos de meu povo, para jurar em meu nome, [dizendo] : Vive o SENHOR, assim como ensinaram a meu povo a jurar por Baal; eles serão edificados em meio do meu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 12, 17, 'Porém, se não quiserem ouvir, arrancarei à tal nação por completo, e a destruirei, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 13, 1, 'Assim me disse o SENHOR: Vai, e compra para ti um cinto de linho, e o põe sobre teus lombos; e não o metas em água.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 13, 2, 'E comprei o cinto conforme à palavra do SENHOR, e o pus sobre meus lombos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 13, 3, 'E veio a mim a palavra do SENHOR pela segunda vez, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 13, 4, 'Toma o cinto que compraste, que está sobre teus lombos, levanta-te, e vai ao Eufrates, e ali o escondes na fenda de uma rocha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 13, 5, 'Então eu fui, e o escondi em Eufrates, como o SENHOR tinha me mandado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 13, 6, 'E sucedeu, que ao fim de muitos dias, o SENHOR me disse: Levanta-te, vai ao Eufrates, e toma dali o cinto que ali te mandei esconder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 13, 7, 'Então fui ao Eufrates, cavei, e tomei o cinto do lugar de onde o havia escondido; e eis que o cinto tinha se apodrecido; para nada mais prestava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 13, 8, 'Então veio a mim palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 13, 9, 'Assim diz o SENHOR: assim farei apodrecer a arrogância de Judá, e a grande arrogância de Jerusalém,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 13, 10, 'Este povo maligno, que recusa ouvir minhas palavras, que caminha conforme a teimosia de seu coração, e segue atrás de deuses estrangeiros para lhes servir, e para se encurvar a eles; e tal será como este cinto, que para nenhuma coisa presta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 13, 11, 'Porque assim como o cinto está junto aos lombos do homem, assim fiz juntar a mim toda a casa de Israel e toda a casa de Judá,diz o SENHOR, para que me fossem por povo e por nome, e por louvor e por glória; porém não [quiseram] escutar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 13, 12, 'Por isso dize-lhes esta palavra: Assim diz o SENHOR, Deus de Israel: Todo odre se encherá de vinho. E te dirão: Por acaso nós não sabemos muito bem que todo odre se encherá de vinho?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 13, 13, 'Então dize-lhes: Assim diz o SENHOR: Eis que eu encherei de embriaguez todos os moradores desta terra, e aos reis que se sentam sobre o trono de Davi, e aos sacerdotes e aos profetas, e a todos os moradores de Jerusalém;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 13, 14, 'E eu os despedaçarei um contra o outro, e juntamente os pais com os filhos, diz o SENHOR; não perdoarei, nem pouparei, nem terei compaixão; nada me impedirá de destruí-los.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 13, 15, 'Escutai e ouvi: não sejais arrogantes, pois o SENHOR falou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 13, 16, 'Dai glória ao SENHOR vosso Deus, antes que ele faça escurecer, e antes que vossos pés tropecem nos montes no meio da escuridão, e espereis luz, e ele a torne em sombra de morte e cause trevas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 13, 17, 'Mas se não ouvirdes isto, minha alma chorará em segredo por causa de [vossa] arrogância; e chorando amargamente, meus olhos se desfarão em lágrimas, porque o rebanho do SENHOR foi levado cativo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 13, 18, 'Dize ao rei e à rainha-mãe: Humilhai-vos, sentai-vos rebaixados; porque a coroa de vossa glória já caiu de vossas cabeças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 13, 19, 'As cidades do Negueve estão fechadas, e ninguém há que [as] abra; toda Judá foi levada, ela foi levada cativa por completo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 13, 20, 'Levantai vossos olhos, e vede os que vêm do norte; onde está o rebanho que te foi dado, a ovelhas de tua glória?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 13, 21, 'O que dirás quando ele te punir? Pois tu os ensinaste a serem príncipes e cabeça sobre ti. Por acaso as dores não te tomarão, como uma mulher em parto?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 13, 22, 'E quando disseres em teu coração: Por que estas coisas me aconteceram? [A resposta é] : Foi pela grandeza de tua maldade que tuas roupas foram descobertas, e foste violentada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 13, 23, 'Pode o negro mudar a sua pele, ou o leopardo suas manchas? Assim também podeis vós fazer o bem, sendo tão acostumados a praticar o mal?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 13, 24, 'Portanto eu os espalharei como os restos de palha que passam com o vento do deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 13, 25, 'Isto é o que terás, a porção de tuas medidas que te reservo, diz o SENHOR; pois tu te esqueceste de mim, e confiaste na mentira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 13, 26, 'Asim também eu descobrirei também tuas roupas até sobre teu rosto, e tua desonra ficará à mostra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 13, 27, 'Eu vi as tuas abominações: teus adultérios, teus relinchos, a maldade de tua prostituição sobre os morros no campo. Ai de ti, Jerusalém! Até quando continuarás sem te purificares?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 14, 1, 'Palavra do SENHOR que veio a Jeremias, quanto à seca:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 14, 2, 'Judá está de luto, e suas portas se enfraqueceram; lamentam até o chão, e o clamor de Jerusalém está a subir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 14, 3, 'E os mais ilustres deles enviaram seus inferiores à água; eles vêm aos tanques, [e] não acham água; voltam com seus vasos vazios; eles se envergonham, se sentem humilhados, e cobrem suas cabeças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 14, 4, 'Pois o chão se rachou, por não haver chuva na terra; envergonhados estão os trabalhadores, [e] cobrem suas cabeças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 14, 5, 'E até as cervas nos campos geram filhotes, e os abandonam, pois não há erva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 14, 6, 'E os asnos monteses se põem nos lugares altos, aspiram o vento como os chacais; seus olhos se enfraquecem, pois não há erva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 14, 7, 'Ainda nossas maldades dão testemunho contra nós, SENHOR, age por amor de teu nome; pois nossas rebeldias se multiplicaram, contra ti pecamos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 14, 8, 'Ó tu, esperança de Israel, Redentor seu em tempo de angústia! Por que serias tu como um peregrino na terra, e como um caminhante que [apenas] se recolhe para passar a noite?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 14, 9, 'Por que serias tu como um homem atônito, e como um guerreiro que não pode salvar? Tu porém estás no meio de nós nós, ó SENHOR, e nós somos chamados pelo teu nome! Não nos desampares.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 14, 10, 'Assim diz o SENHOR quanto a este povo: Já que amaram tanto se moverem, e detiveram seus pés, por isso o SENHOR não se agrada deles; agora se lembrará da maldade deles, e punirá por causa de seus pecados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 14, 11, 'Disse-me mais o SENHOR: Não rogues pelo bem deste povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 14, 12, 'Quando jejuam, não ouvirei seu clamor, e quando oferecem sacrifícios de queima e ofertas de cereais, não os aceitarei; em vez disso, eu os consumirei por meio da espada, da fome, e da pestilência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 14, 13, 'Então eu disse: Ah, Senhor DEUS! Eis que os profetas lhes dizem: Não vereis espada, nem tereis fome; eu, porém, vos darei uma paz verdadeira neste lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 14, 14, 'Então o SENHOR me disse: Os profetas profetizam falsidade em meu nome; eu não os enviei, nem lhes mandei, nem lhes falei; eles vos profetizam visão falsa, adivinhação, inutilidade, e engano de seus [próprios] corações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 14, 15, 'Portanto assim diz o SENHOR quanto aos profetas que profetizam em meu nome, sem que eu tenha lhes enviado, que dizem “não haverá nem espada nem fome nesta terra”: Com espada e com fome tais profetas serão consumidos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 14, 16, 'E o povo a quem eles profetizam será lançado fora nas ruas de Jerusalém, por causa da fome e da espada; e não haverá quem os enterre, eles, suas mulheres, seus filhos, e suas filhas; e sobre eles derramarei sua maldade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 14, 17, 'Portanto tu lhes dirás esta palavra: Corram meus olhos em lágrimas noite e dia, e não cessem; porque a virgem filha de meu povo está quebrada de grande quebrantamento, [de] praga muito dolorosa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 14, 18, 'Se saio ao campo, eis os mortos a espada; e se entro na cidade, eis os doentes de fome; e até os profetas e os sacerdotes andam rodeando na terra, e nada sabem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 14, 19, 'Rejeitaste a Judá por completo? Tua alma detesta a Sião? Por que nos feriste [de modo] que não haja cura para nós? Esperávamos paz, mas nada há de bom; [esperávamos] tempo de cura, e eis o terror!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 14, 20, 'Ó SENHOR, reconhecemos nossa perversidade, a maldade de nossos pais; pois pecamos contra ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 14, 21, 'Não [nos] rejeites por amor de teu nome, nem desonres ao trono de tua glória; lembra-te, não invalides o teu pacto conosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 14, 22, 'Por acaso há entre as futilidades das nações alguém que faz chover? Ou podem os céus dar chuvas? Não és [somente] tu, SENHOR, nosso Deus? Por isso em ti esperamos, pois tu fazes todas estas coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 15, 1, 'Disse-me, porém, o SENHOR: Ainda que Moisés e Samuel se pusessem diante de mim, minha boa vontade não seria com este povo. Lança-os de diante de mim, e saiam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 15, 2, 'E será que, quando te perguntarem: Para onde sairemos? Tu lhes dirás: Assim diz o SENHOR: Os que são para a morte, para a morte; e os que são para a espada, para a espada; e os que são para a fome, para a fome; e os que são para o cativeiro, para o cativeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 15, 3, 'Pois eu lhes darei quatro tipos de castigos, diz o SENHOR: espada para matar, cães para despedaçar, e aves do céu e animais da terra para devorar e para destruir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 15, 4, 'E farei deles que sejam motivo de horror a todos os reinos da terra, por causa de Manassés filho de Ezequias rei de Judá, pelo que ele fez em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 15, 5, 'Pois quem terá compaixão de ti, ó Jerusalém? Ou quem se entristecerá por tua causa? Ou quem se desviaria para perguntar se estás bem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 15, 6, 'Tu me deixaste, diz o SENHOR, voltaste para trás [de mim] ; por isso estenderei minha mão contra ti, e te destruirei; já estou cansado de sentir pena.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 15, 7, 'E eu os padejarei com pá até as portas da terra, [e os] deixarei sem filhos; destruirei meu povo, pois não voltaram atrás de seus caminhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 15, 8, 'Suas viúvas se multiplicaram mais que a areia dos mares; eu lhes trouxe sobre a mãe dos rapazes um destruidor ao meio dia; sobre ela eu fiz cair de angústia e terrores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 15, 9, 'Enfraqueceu-se a que teve sete filhos; a sua alma perdeu o fôlego; seu sol se lhe pôs, sendo ainda de dia; envergonhou-se, e ficou humilhada; e os que dela restarem, eu os entregarei a espada diante de seus inimigos,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 15, 10, 'Ai de mim, minha mãe, que me geraste homem de brigas e homem de confrontos a toda a terra! Nunca lhes emprestei a juros, nem deles emprestado; e [mesmo assim] todos eles me amaldiçoam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 15, 11, 'Disse o SENHOR: Certamente eu te livrarei para o bem; certamente intervirei por ti no tempo do mal, e no tempo de angústia, por causa do inimigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 15, 12, 'Pode, por acaso o ferro [comum] quebrar o ferro do norte, ou o bronze?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 15, 13, 'Tuas riquezas e teus tesouros darei ao despojo por preço nenhum, por todos os teus pecados, e em todos os teus limites;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 15, 14, 'E [te] levarei com teus inimigos a uma terra que não conheces; porque fogo se acendeu em minha ira, que arderá sobre vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 15, 15, 'Tu sabes, ó SENHOR; lembra-te de mim, visita-me, e vinga-me de meus perseguidores. Na lentidão de tua ira não me elimines; tu sabes que é por causa de ti que sofro insultos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 15, 16, 'Achando-se tuas palavras, logo eu as comi; e tua palavra me foi por prazer e por alegria a meu coração; pois me chamo pelo teu nome, ó SENHOR Deus dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 15, 17, 'Não me sentei em companhia de zombadores, nem [com eles] me alegrei; por causa de tua mão, eu me sentei sozinho, pois me encheste de indignação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 15, 18, 'Por que minha dor é contínua, e minha ferida intratável, que não permite cura? Por acaso serias tu para mim como uma ilusão, como águas que não se pode confiar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 15, 19, 'Portanto assim diz o SENHOR: Se te converteres, eu te restaurarei, e diante de mim estarás; e se tirares o que é de precioso ao invés do vil, serás como minha boca. Convertam-se eles a ti, e tu não te convertas a eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 15, 20, 'Pois eu te porei para este povo [para seres] como um forte muro de bronze; e lutarão contra ti, mas não te vencerão; pois eu estou contigo para te guardar e te livrar,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 15, 21, 'E eu te livrarei da mão dos maus, e te resgatarei da mão dos terríveis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 16, 1, 'E veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 16, 2, 'Não tomes para ti mulher, nem tenhas filhos nem filhas neste lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 16, 3, 'Porque assim diz o SENHOR quanto aos filhos e às filhas que nascerem neste lugar, e às suas mães que os tiverem e aos pais que os gerarem nesta terra:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 16, 4, 'De dolorosas enfermidades morrerão; não serão pranteados nem sepultados; servirão de esterco sobre a face da terra; e com espada e com fome serão consumidos, e seus cadáveres servirão de alimento para as aves do céu e para os animais da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 16, 5, 'Porque assim diz o SENHOR: Não entres em casa de luto, nem vás para lamentar, nem mostre compaixão deles; pois deste povo eu tirei minha paz, bondade e misericórdia, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 16, 6, 'E nesta terra morrerão grandes e pequenos; não serão sepultados, nem pranteados, nem por eles se cortarão, ou rasparão seus cabelos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 16, 7, 'Nem repartirão pão aos que estiverem de luto, para consolá-los de seus mortos; nem lhes darão a beber copo de consolações pelo pai ou pela mãe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 16, 8, 'Nem também entres em casa de banquete, para te sentares com eles para comer e beber;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 16, 9, 'Porque assim diz o SENHOR dos exércitos, Deus de Israel: Eis que farei cessar neste lugar, diante de vossos olhos e em vossos dias, toda voz de prazer e toda voz de alegria, toda voz de noivo e toda voz de noiva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 16, 10, 'E será que quando anunciares a este povo todas estas palavras, eles te dirão: Por que o SENHOR falou sobre nós este mal tão grande? E que maldade é a nossa, ou que pecado é o nosso, que cometemos contra o SENHOR nosso Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 16, 11, 'Então lhes dirás: Porque vossos pais me deixaram, diz o SENHOR, e seguiram deuses estrangeiros, os serviram e a eles se prostraram; e me abandonaram, e não guardaram minha Lei;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 16, 12, 'E vós fizestes pior que vossos pais; pois eis que vós caminhais cada um atrás da teimosia de seu coração maligno, sem me obedecerem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 16, 13, 'Por isso eu vos lançarei fora desta terra, para uma terra que nem vós nem vossos pais conhecestes; e lá servireis a deuses estrangeiros de dia e de noite, porque não terei misericórdia de vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 16, 14, 'Porém eis que vêm dias, diz o SENHOR, que não se dirá mais: Vive o SENHOR, que trouxe os filhos de Israel da terra do Egito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 16, 15, 'Mas sim: Vive o SENHOR, que trouxe os filhos de Israel da terra do norte, e de todas as terras aonde ele tinha os lançado; pois eu os farei voltar à sua terra, a qual dei a seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 16, 16, 'Eis que enviarei muitos pescadores, diz o SENHOR, que os pescarão; e depois enviarei muitos caçadores, que os caçarão de todo monte, e de todo morro, e até das fendas das rochas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 16, 17, 'Pois meus olhos estão sobre todos seus caminhos; eles não estão escondidos de mim, nem a maldade deles está oculta de diante de meus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 16, 18, 'Mas primeiro pagarei em dobro a iniquidade e o pecado deles, pois contaminaram minha terra com os cadáveres de suas coisas detestáveis, e encheram minha herança de suas abominações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 16, 19, 'Ó SENHOR, fortaleza minha, e força minha, e meu refúgio no tempo da aflição; a ti virão nações desde os confins da terra, e dirão: Certamente o que nossos pais possuíam era mentira e inutilidade; não havia nessas coisas proveito algum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 16, 20, 'Pode, por acaso, o homem fazer deuses para si? Eles, porém, não são deuses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 16, 21, 'Portanto eis que desta vez lhes farei conhecer, lhes farei conhecer minha mão e meu poder, e saberão que EU-SOU é o meu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 17, 1, 'O pecado de Judá está escrito com cinzel de ferro, com ponta de diamante; está esculpido na tábua de seu coração, e nas pontas de vossos altares;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 17, 2, 'Enquanto seus filhos se lembram de seus altares e de seus bosques, junto às árvores verdes, sobre os altos morros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 17, 3, 'Ó minha montanha no campo! Tua riqueza e todos os teus tesouros darei como despojo por causa do pecado de teus altos em todos teus limites.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 17, 4, 'Assim por causa de ti deixarás de ter a herança que eu te dei, e te farei servir a teus inimigos em uma terra que não conheces; porque acendestes fogo em minha ira, que arderá para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 17, 5, 'Assim diz o SENHOR: Maldito o homem que confia no homem, e põe sua confiança na força humana, ) e seu coração se afasta do SENHOR;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 17, 6, 'Pois será como um arbusto no deserto, e não sente quando vier o bem; ao invés disso morará nas securas no deserto, em terra salgada e inabitável.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 17, 7, 'Bendito o homem que confia no SENHOR, cuja confiança é o SENHOR;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 17, 8, 'Porque ele será como a árvore plantada junto a águas, que estende suas raízes junto à corrente; não tem preocupação quando vier o calor, e sua folha permanece verde; e no ano de seca não se cansa, nem deixa de dar fruto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 17, 9, 'O coração é mais enganoso que todas as coisas, e perverso; quem pode conhecê-lo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 17, 10, 'Eu, o SENHOR, que examino o coração, e provo os sentimentos, para dar a cada um conforme seus caminhos, conforme o fruto de suas ações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 17, 11, '[Como] a perdiz que choca [os ovos] que não pôs, [assim] é o que junta riquezas, mas não com justiça; no meio de seus dias ele deixará de tê-las, e em seu fim ele será tolo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 17, 12, 'Trono de glória, elevado desde o princípio, é o lugar de nosso santuário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 17, 13, 'Ó SENHOR, esperança de Israel! Todos os que te abandonam serão envergonhados; e os que de mim se afastam, serão escritos no chão; pois abandonaram ao SENHOR, a fonte de águas vivas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 17, 14, 'Sara-me, ó SENHOR, e serei sarado; salva-me, e serei salvo; pois tu és meu louvor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 17, 15, 'Eis que eles me dizem: Onde está a palavra do SENHOR? Cumpra-se ela agora!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 17, 16, 'Mas eu não me apressei para deixar de ser ser pastor após ti, nem desejei o dia de calamidade, tu o sabes. O que saiu de minha boca foi em tua presença.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 17, 17, 'Não sejas tu assombro para mim; tu és minha esperança no dia mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 17, 18, 'Envergonhem-se os que me perseguem, e eu não me envergonhe; assombre-se eles, e eu não me assombre: traze sobre eles o dia mal, e destrói-os com destruição dobrada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 17, 19, 'Assim me disse o SENHOR: Vai, e põe-te à porta dos filhos do povo, pela qual entram e saem os reis de Judá, e a todas as portas de Jerusalém,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 17, 20, 'E dize-lhes: Ouvi a palavra do SENHOR, vós reis de Judá, e todo Judá, e todos os moradores de Jerusalém que entrais por esta portas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 17, 21, 'Assim diz o SENHOR: Guardai-vos por vossas vidas, e não tragais carga no dia do sábado, para fazê-las entrar pelas portas de Jerusalém;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 17, 22, 'Nem tireis carga de vossas casas no dia do sábado, nem façais obra alguma; ao invés disso, santificai o dia do sábado, assim como mandei a vossos pais;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 17, 23, 'Porém eles não deram ouvidos, nem escutaram; ao invés disso, tornaram-se teimosos, ) para não ouvirem, nem receberem correção.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 17, 24, 'Será, pois, se vós me ouvirdes cuidadosamente, diz o SENHOR, não fazendo entrar carga pelas portas desta cidade no dia do sábado, e santificardes o dia do sábado, não fazendo nele nenhuma obra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 17, 25, 'Então entrarão pelas portas desta cidade reis e os príncipes que se sentem sobre o trono de Davi, [montados] em carros e em cavalos; eles e seus príncipes, e os homens de Judá, e os moradores de Jerusalém; e esta cidade será habitada para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 17, 26, 'E [pessoas] virão das cidades de Judá, dos arredores de Jerusalém, da terra de Benjamim, dos campos, do monte, e do Negueve, trazendo holocaustos, sacrifícios, ofertas de alimento e incensos, e trazendo sacrifícios de louvor à casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 17, 27, 'Porém se não me ouvirdes para santificardes o dia do sábado, e para não trazerdes carga nem fazê-la entrar pelas portas de Jerusalém no dia de sábado, eu acenderei fogo em suas portas, que consumirá os palácios de Jerusalém, e não se apagará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 18, 1, 'Palavra que veio do SENHOR a Jeremias, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 18, 2, 'Levanta-te, e desce à casa do oleiro; e ali te farei ouvir minhas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 18, 3, 'Então desci à casa do oleiro, e eis que ele estava fazendo uma obra sobre a roda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 18, 4, 'E o vaso de barro que ele estava fazendo se quebrou na mão do oleiro; então ele voltou a fazer dele outro vaso, conforme o que ao oleiro pareceu melhor fazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 18, 5, 'Então veio a mim palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 18, 6, 'Por acaso não poderei eu fazer de vós como este oleiro, ó casa de Israel?diz o SENHOR. Eis que tal como o barro na mão do oleiro, assim sois vós em minha mão, ó casa de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 18, 7, 'Caso em algum momento eu falar contra uma nação e contra um reino, para arrancar, dissipar, e destruir,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 18, 8, 'Se tal nação se converter de sua maldade, contra a qual falei, eu mudarei de ideia quanto ao mal que tinha pensado lhe fazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 18, 9, 'Caso em algum momento eu falar de uma nação e de um reino, para edificar e para plantar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 18, 10, 'Se ela fizer o mal diante dos meus olhos, não obedecendo à minha voz, eu mudarei de ideia quanto ao bem que tinha dito lhe fazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 18, 11, 'Então agora, fala, pois, a todo homem de Judá, e aos moradores de Jerusalém, dizendo: Assim diz o SENHOR: Eis que eu determino o mal contra vós, e faço planos contra vós; convertei-vos agora, cada um de seu mau caminho, e melhorai vossos caminhos e vossas ações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 18, 12, 'Porém dizem: Não há esperança; porque seguiremos nossas [próprias] intenções, e faremos cada um o pensamento de seu maligno coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 18, 13, 'Portanto assim diz o SENHOR: Perguntai agora entre as nações, quem tenha ouvido tal coisa. Grande horror fez a virgem de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 18, 14, 'Por acaso pode faltar neve nas rochas das montanhas do Líbano? Ou pode deixar de haver as águas frias que correm de terras distantes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 18, 15, 'Porém meu povo se esqueceu de mim, queimando incenso à inutilidade, e fazem- lhes tropeçar em seus caminhos, [nas] veredas antigas, para que andassem por veredas de caminho não aplanado;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 18, 16, 'Para tornar sua terra em desolação, e em assovios perpétuos; todo aquele que passar por ela se espantará e balançará sua cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 18, 17, 'Tal como vento oriental, eu os espalharei diante do inimigo; eu lhes mostrarei as costas, e não o rosto, no dia de sua perdição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 18, 18, 'Então disseram: Vinde, e façamos planos contra Jeremias; porque a Lei não perecerá do sacerdote, nem o conselho do sábio, nem a palavra do profeta. Vinde e o firamos com a língua, e não prestemos atenção a nenhuma de suas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 18, 19, 'Ó SENHOR, presta atenção a mim, e ouve a voz dos que brigam comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 18, 20, 'Por acaso se pagará ao bem com o mal? Pois já cavaram uma cova para a minha alma! Lembra-te que me pus diante de ti para falar pelo bem deles, para desviar deles a tua ira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 18, 21, 'Portanto entrega os filhos deles à fome, e derrama-os pelo poder da espada; e restem suas mulheres sem filhos e viúvas; e seus maridos sejam postos a morte, e seus rapazes sejam feridos à espada na guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 18, 22, 'Ouçam-se gritos de suas casas, quando tu trouxeres tropas contra eles de repente; pois cavaram uma cova para me prender, e armaram laços para meus pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 18, 23, 'Mas tu, SENHOR, conheces todo o plano deles contra mim para me matar; não perdoes sua maldade, nem apagues o pecado deles de diante de tua presença, e tropecem diante de ti; faze [assim] com eles no tempo de tua ira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 19, 1, 'Assim diz o SENHOR: Vai, e compra uma jarra de barro de oleiro, e [toma contigo] dos anciãos do povo e dos anciãos dos sacerdotes;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 19, 2, 'E sai ao vale do filho de Hinom, que fica à entrada da porta oriental; e ali declara as palavras que eu te disser.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 19, 3, 'E dize: Ouvi a palavra do SENHOR, ó reis de Judá, e moradores de Jerusalém. Assim diz o SENHOR dos exércitos, Deus de Israel: Eis que trarei calamidade sobre este lugar, de tal modo que quem o ouvir, lhe retinirão os ouvidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 19, 4, 'Pois me abandonaram, e profanaram este lugar, e queimaram nele incenso a outros deuses, que nunca tinham conhecido, nem eles, nem seus pais, nem os reis de Judá; e encheram este lugar com sangue de inocentes;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 19, 5, 'E edificaram altares a Baal, para queimarem a fogo seus filhos [como] holocaustos a Baal; coisa esta que nunca [lhes] mandei, nem falei, nem jamais pensei em meu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 19, 6, 'Por isso eis vêm dias, diz o SENHOR, que este lugar não se chamará mais Tofete, nem Vale do filho de Hinom, mas sim Vale da Matança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 19, 7, 'E tornarei vazio o conselho de Judá e de Jerusalém neste lugar; e os farei cair à espada diante de seus inimigos, e nas mãos dos que buscam [tirar] suas vidas; e darei seus cadáveres por comida às aves do céu e aos animais da terra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 19, 8, 'E farei desta cidade espanto e assovio; todo aquele que passar por ela se espantará e assoviará por causa de todas as suas pragas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 19, 9, 'E farei com que comam a carne de seus filhos e a carne de suas filhas; e cada um comerá a carne de seu próximo durante o cerco e a opressão com que os seus inimigos e os que buscam [tirar] suas vidas lhes oprimirão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 19, 10, 'Então quebrarás a jarra perante os olhos dos homens que tiverem ido contigo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 19, 11, 'E lhes dirás: Assim diz o SENHOR dos exércitos: Assim quebrarei a este povo e a esta cidade, como quem quebra um vaso de oleiro, que não pode mais ser restaurado; e em Tofete serão enterrados, pois não haverá [outro] lugar para enterrar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 19, 12, 'Assim farei a este lugar, diz o SENHOR, e a seus moradores, para fazer desta cidade como a Tofete.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 19, 13, 'E as casas de Jerusalém, e as casas dos reis de Judá, serão imundas tal como o lugar de Tofete; todas as casas sobre cujos telhados foi queimado incenso a todo o exército do céu, e derramaram ofertas de bebida a deuses estrangeiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 19, 14, 'Então voltou Jeremias de Tofete, onde o SENHOR tinha lhe mandado profetizar, e se pôs em pé no pátio da casa do SENHOR, e disse a todo o povo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 19, 15, 'Assim diz o SENHOR dos exércitos, Deus de Israel: Eis que eu trago sobre esta cidade e sobre todas as suas vilas todo o mal que falei contra ela; pois endureceram seu pescoço para não ouvirem minhas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 20, 1, 'E Pasur, filho de Imer, o sacerdote, que era o principal supervisor na casa do SENHOR, ouviu a Jeremias enquanto profetizava estas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 20, 2, 'Então Pasur feriu ao profeta Jeremias, e o pôs no tronco que ficava à porta superior de Benjamim, a qual fica na casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 20, 3, 'E foi no dia seguinte que Pasur tirou a Jeremias do tronco. Disse-lhe então Jeremias: O SENHOR não chama teu nome Pasur, mas sim “Terror por todos os lados”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 20, 4, 'Porque assim diz o SENHOR: Eis que eu farei de ti um terror a ti mesmo, e a todos os teus amigos; e cairão pelo espada de seus inimigos, e teus olhos o verão; e a todo Judá entregarei na mão do rei da Babilônia, e os levará cativos a Babilônia, e os ferirá à espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 20, 5, 'Entregarei também toda a riqueza desta cidade, e todo seu trabalho, e todas suas coisas preciosas; e entregarei todos os tesouros dos reis de Judá nas mãos de seus inimigos, e os saquearão, e os tomarão, e os levarão a Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 20, 6, 'E tu, Pasur, e todos os moradores de tua casa ireis ao cativeiro, e entrarás na Babilônia, e ali morrerás; e ali serás sepultado, tu, e todos os teus amigos, aos quais profetizaste falsamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 20, 7, 'Persuadiste-me, ó SENHOR, e eu fiquei persuadido; mais forte foste que eu, e prevaleceste; sirvo de escárnio o dia todo; cada deles zomba de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 20, 8, 'Pois desde que falo, grito; eu clamo violência e destruição; pois a palavra do SENHOR tem me servido de insulto e zombaria o dia todo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 20, 9, 'Então eu disse: Não me lembrarei dele, nem falarei mais em seu nome; porém [ela] foi em meu coração como um fogo ardente contido em meus ossos; resisti até me cansar, mas não pude.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 20, 10, 'Porque ouço a murmuração de muitos, temor por todos os lados: Anunciai, e anunciaremos. Todos os meus amigos observam meu manquejar, [dizendo] : Talvez se enganará; então prevaleceremos contra ele, e nos vingaremos dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 20, 11, 'Mas o SENHOR está comigo como temível guerreiro; por isso meus perseguidores tropeçarão, e não prevalecerão; eles serão muito envergonhados, por não terem agido prudentemente; [terão] humilhação perpétua, que jamais será esquecida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 20, 12, 'Tu, SENHOR dos exércitos, que examinas o justo, que vês os sentimentos e pensamentos, faz-me ver a tua vingança sobre eles; pois a ti revelei a minha causa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 20, 13, 'Cantai ao SENHOR, louvai ao SENHOR; pois ele livra a alma do necessitado da mão dos malfeitores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 20, 14, 'Maldito seja o dia em que nasci! O dia em que minha mãe me teve não seja bendito!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 20, 15, 'Maldito seja o homem que deu as novas a meu pai, dizendo, Um filho macho te nasceu, trazendo-lhe assim muita alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 20, 16, 'E seja tal homem como as cidades que o SENHOR assolou sem se arrepender; e ouça gritos de manhã, e clamores ao meio dia;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 20, 17, 'Por ele não ter me matado no ventre, de modo que minha mãe teria sido minha sepultura, e o ventre uma gravidez perpétua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 20, 18, 'Para que saí do ventre? Para ver trabalho e dor, e meus dias serem gastos com vergonha?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 21, 1, 'Palavra que veio do SENHOR a Jeremias, quando o rei Zedequias lhe enviou a Pasur filho de Malquias, e a Sofonias, sacerdote, filho de Maaseias, para que lhe dissessem:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 21, 2, 'Pergunta agora por nós ao SENHOR; pois Nabucodonosor, rei da Babilônia, está fazendo guerra contra nós; talvez o SENHOR faça conosco segundo todas as suas maravilhas, e o mande embora de sobre nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 21, 3, 'E Jeremias lhes disse: Direis assim a Zedequias:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 21, 4, 'Assim diz o SENHOR Deus de Israel: Eis que eu virarei para trás as armas de guerra que estão em vossas mãos, com as quais lutais contra o rei da Babilônia e os Caldeus que vos têm cercado fora da muralha; e eu os juntarei no meio desta cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 21, 5, 'E eu mesmo lutarei contra vós com mão estendida e com braço forte; e com ira, indignação, e grande furor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 21, 6, 'E ferirei aos moradores desta cidade; tanto aos homens quanto aos animais; morrerão de grande pestilência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 21, 7, 'E depois, assim diz o SENHOR, entregarei a Zedequias rei de Judá, e a seus servos, e ao povo, e aos que restarem na cidade da pestilência, da espada, e da fome, nas mãos de Nabucodonosor rei de Babilônia, nas mãos de seus inimigos, e na mão dos que buscam [tirar] suas vidas. Ele os matará ao fio de espada; não lhes poupará, nem terá deles compaixão, nem misericórdia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 21, 8, 'E a este povo dirás: Assim diz o SENHOR: Eis que ponho diante de vós caminho de vida e caminho de morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 21, 9, 'Aquele que permanecer nesta cidade, morrerá a espada, ou pela fome, ou pela pestilência; mas o que sair e se render aos Caldeus, que têm vos cercado, viverá, e terá sua vida como despojo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 21, 10, 'Porque pus meu rosto contra esta cidade para o mal, e não para o bem, diz o SENHOR; nas mãos do rei de Babilônia será entregue, e ele a queimará a fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 21, 11, 'E à casa do rei de Judá dirás: Ouvi palavra do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 21, 12, 'Casa de Davi, assim diz o SENHOR: Julgai de manhã com justiça, e livrai a vítima de roubo da mão do opressor; para que minha ira não saia como fogo, e incendeie de modo que não haja quem apague, por causa da maldade de vossas ações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 21, 13, 'Eis que eu [sou] contra ti, ó moradora do vale, da rocha do planalto, diz o SENHOR; [contra] vós que dizeis: Quem descerá contra nós? E quem entrará em nossas moradas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 21, 14, 'Eu vos punirei conforme o fruto de vossas ações, diz o SENHOR, e acenderei fogo em seu bosque, que consumirá tudo o que estiver ao redor dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 22, 1, 'Assim diz o SENHOR: Desce à casa do rei de Judá, e fala ali esta palavra,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 22, 2, 'E dize: Ouve a palavra do SENHOR, ó rei de Judá, que te sentas sobre o trono de Davi; tu, teus servos, e teu povo, que entrais por estas portas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 22, 3, 'Assim diz o SENHOR: Fazei juízo e justiça, e livrai a vítima de roubo da mão do opressor, e não oprimais, nem façais violência contra o estrangeiro, o órfão, ou à viúva, nem derrameis sangue inocente neste lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 22, 4, 'Porque se verdadeiramente cumprirdes esta palavra, os reis que se sentam em lugar de Davi sobre seu trono entrarão montados sobre carruagens e sobre cavalos pelas portas desta casa; eles, e seus servos, e seu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 22, 5, 'Porém se não obedecerdes estas palavras, por mim mesmo tenho jurado, diz o SENHOR, que esta casa se tornará deserta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 22, 6, 'Porque assim diz o SENHOR quanto à casa do rei de Judá: Tu és para mim [como] Gileade, [e] o topo do Líbano; porém certamente te tornarei em deserto, [e] cidades desabitadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 22, 7, 'Pois prepararei contra ti destruidores, cada um com suas armas; e cortarão teus mais valiosos cedros, e os lançarão no fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 22, 8, 'E muitas nações passarão junto a esta cidade; e cada um dirá a seu companheiro: Por que o SENHOR fez isto com esta grande cidade?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 22, 9, 'E responderão: Porque deixaram o pacto do SENHOR seu Deus, e adoraram a deuses estrangeiros, e os serviram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 22, 10, 'Não choreis pelo morto, nem dele vos lastimeis; mas chorai mesmo por aquele que vai embora; porque nunca mais voltará, nem verá a terra onde nasceu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 22, 11, 'Porque assim diz o SENHOR quanto a Salum, filho de Josias, rei de Judá, que reinava em lugar de Josias seu pai, que saiu deste lugar: Nunca mais voltará;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 22, 12, 'Em vez disso, morrerá no lugar aonde o levaram cativo, e nunca mais verá esta terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 22, 13, 'Ai daquele que edifica sua casa com injustiça, e seus cômodos sem fazer o que é correto, que usa do serviço de seu próximo de graça, sem lhe dar o pagamento de seu trabalho!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 22, 14, 'Que diz: Edificarei para mim uma casa ampla, com cômodos arejados; e lhe abre janelas, e a cobre de cedro, e a pinta de vermelho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 22, 15, 'Por acaso é acumulando cedro que serás rei? Por acaso teu pai não comeu e bebeu, e fez juízo e justiça, [e] então teve o bem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 22, 16, 'Ele julgou a causa do aflito e do necessitado, e então esteve bem. Por acaso conhecer a mim não é isto?diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 22, 17, 'Mas teus olhos e teu coração não são [para outra coisa] , a não ser para tua ganância, para derramar sangue inocente, e para praticar opressão e violência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 22, 18, 'Portanto assim diz o SENHOR quanto a Jeoaquim, filho de Josias, rei de Judá: Não lamentarão por ele, dizendo: Ai meu irmão!, ou Ai minha irmã!, Nem lamentarão por ele, dizendo: Ai senhor! Ai sua majestade!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 22, 19, 'Com sepultamento de asno será sepultado; arrastando e lançando [-o] longe, fora das portas de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 22, 20, 'Sobe ao Líbano, e clama, levanta tua voz em Basã, e grita desde Abarim; porque todos teus amantes estão destruídos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 22, 21, 'Falei contigo em tuas prosperidades; [mas] disseste: Não ouvirei. Este tem sido o teu caminho desde tua juventude, que nunca deste ouvidos à minha voz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 22, 22, 'O vento apascentará a todos os teus pastores, e teus amantes irão ao cativeiro; então certamente te envergonharás e te humilharás por causa de toda a tua maldade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 22, 23, 'Tu, que habitas no Líbano, que fazes teu ninho nos cedros: como gemerás quando te vierem as dores, os sofrimentos como de mulher em parto!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 22, 24, 'Vivo eu,diz o SENHOR, que se Conias, filho de Jeoaquim rei de Judá, fosse um anel em minha mão direita, até dali eu te arrancaria;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 22, 25, 'E eu te entregarei na mão dos que buscam a tua vida, e na mão daqueles a quem tu temes: na mão de Nabucodonosor rei da Babilônia, e nas mão dos Caldeus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 22, 26, 'E lançarei a ti e a tua mãe, que te fez nascer, em uma terra estrangeira, em que não nascestes; e lá morrereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 22, 27, 'Mas a terra à qual suas almas anseiam voltar, para lá nunca voltarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 22, 28, 'É este homem Conias um pote quebrado, ou um vaso de quem ninguém se agrada? Por que ele e sua geração foram arremessados fora, e lançados a uma terra que não conhecem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 22, 29, 'Terra, terra, terra: ouve a palavra do SENHOR!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 22, 30, 'Assim diz o SENHOR: Escrevei este homem como sem filhos, homem a quem nada prosperará nos dias de sua vida; pois nenhum homem de sua semente prosperará em se sentar sobre o trono de Davi, e em reinar em Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 1, 'Ai dos pastores que destroem e dispersam as ovelhas de meu rebanho!,Diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 2, 'Portanto assim diz o SENHOR Deus de Israel quanto aos pastores que apascentam meu povo: Vós dispersastes minhas ovelhas, e as afugentastes, e não cuidastes delas; eis que eu cuidarei contra vós pela maldade de vossas ações,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 3, 'E eu mesmo recolherei o restante de minhas ovelhas de todas as terras para onde as afugentei, e as farei voltar a seus apriscos; e crescerão, e se multiplicarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 4, 'E porei sobre elas pastores que as apascentem; e nunca mais temerão, nem se assombrarão, nem haverá falta de uma sequer,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 5, 'Eis que vêm os dias,diz o SENHOR, que levantarei por Davi um justo Renovo, e sendo rei, reinará; o qual prosperará, e fará juízo e justiça na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 6, 'Em seus dias Judá será salvo, e Israel habitará em segurança; e este será seu nome com que o chamarão: O SENHOR é nossa justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 7, 'Portanto eis que vêm dias,diz o SENHOR, que não mais dirão: Vive o SENHOR, que fez subir os filhos de Israel da terra do Egito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 8, 'Mas sim: Vive o SENHOR, que fez subir e trouxe a geração da casa de Israel da terra do norte, e de todas as terras para onde eu os afugentei; e habitarão em sua terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 9, 'Quanto aos profetas: meu coração está quebrantado em meu interior, todos os meus ossos tremem; estou como um homem bêbado, como um homem dominado pelo vinho, por causa do SENHOR, e por causa de suas santas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 10, 'Pois a terra está cheia de adúlteros: e por causa da maldição a terra lamenta; as cabanas do deserto se secaram; pois o percurso deles tem sido mau, e a força deles não é correta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 11, 'Pois tanto o profeta como o sacerdote são corruptos; até em minha casa achei sua maldade,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 12, 'Portanto o caminho deles lhes será como lugares escorregadios na escuridão; serão empurrados, e nele cairão; porque eu trarei mal sobre eles [no] ano de sua punição,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 13, 'Nos profetas de Samaria vi coisas desagradáveis: profetizavam por Baal, e faziam errar a meu povo Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 14, 'Mas nos profetas de Jerusalém tenho vejo coisas horríveis: cometem adultérios, e andam com falsidade, e fortalecem as mãos dos malfeitores, para que ninguém se converta de sua maldade. Para mim, todos eles são como Sodoma, e seus moradores como Gomorra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 15, 'Por isso, assim diz o SENHOR dos exércitos sobre os profetas: Eis que eu lhes darei de comer absinto, e lhes farei beber águas envenenadas; porque dos profetas de Jerusalém a corrupção se espalhou sobre toda a terra.')
